import heapq

class Solution:
    def findCrossingTime(self, n: int, k: int, time: list[list[int]]) -> int:
        left_wait = []
        right_wait = []
        left_work = []
        right_work = []

        for i in range(k):
            p = time[i][0] + time[i][2]
            heapq.heappush(left_wait, (-p, -i))

        cur_time = 0
        rem_boxes = n

        while rem_boxes > 0 or right_wait or right_work:
            while left_work and left_work[0][0] <= cur_time:
                t, neg_p, neg_i = heapq.heappop(left_work)
                heapq.heappush(left_wait, (neg_p, neg_i))

            while right_work and right_work[0][0] <= cur_time:
                t, neg_p, neg_i = heapq.heappop(right_work)
                heapq.heappush(right_wait, (neg_p, neg_i))

            if right_wait:
                neg_p, neg_i = heapq.heappop(right_wait)
                i = -neg_i
                cur_time += time[i][2]
                heapq.heappush(left_work, (cur_time + time[i][3], neg_p, neg_i))
            elif rem_boxes > 0 and left_wait:
                neg_p, neg_i = heapq.heappop(left_wait)
                i = -neg_i
                cur_time += time[i][0]
                rem_boxes -= 1
                heapq.heappush(right_work, (cur_time + time[i][1], neg_p, neg_i))
            else:
                next_t = float('inf')
                if left_work: next_t = min(next_t, left_work[0][0])
                if right_work: next_t = min(next_t, right_work[0][0])
                cur_time = next_t

        return cur_time

class Solution {
public:
    int findCrossingTime(int n, int k, std::vector<std::vector<int>>& time) {
        auto comp_wait = [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        };
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(comp_wait)> left_wait(comp_wait), right_wait(comp_wait);

        auto comp_work = [](const std::vector<int>& a, const std::vector<int>& b) {
            return a[0] > b[0];
        };
        std::priority_queue<std::vector<int>, std::vector<std::vector<int>>, decltype(comp_work)> left_work(comp_work), right_work(comp_work);

        for (int i = 0; i < k; ++i) {
            int p = time[i][0] + time[i][2];
            left_wait.push({p, i});
        }

        int cur_time = 0;
        int rem_boxes = n;

        while (rem_boxes > 0 || !right_wait.empty() || !right_work.empty()) {
            while (!left_work.empty() && left_work.top()[0] <= cur_time) {
                auto w = left_work.top(); left_work.pop();
                left_wait.push({w[1], w[2]});
            }
            while (!right_work.empty() && right_work.top()[0] <= cur_time) {
                auto w = right_work.top(); right_work.pop();
                right_wait.push({w[1], w[2]});
            }

            if (!right_wait.empty()) {
                auto w = right_wait.top(); right_wait.pop();
                int i = w.second;
                cur_time += time[i][2];
                left_work.push({cur_time + time[i][3], w.first, i});
            } else if (rem_boxes > 0 && !left_wait.empty()) {
                auto w = left_wait.top(); left_wait.pop();
                int i = w.second;
                cur_time += time[i][0];
                rem_boxes--;
                right_work.push({cur_time + time[i][1], w.first, i});
            } else {
                int next_t = 2e9;
                if (!left_work.empty()) next_t = std::min(next_t, left_work.top()[0]);
                if (!right_work.empty()) next_t = std::min(next_t, right_work.top()[0]);
                cur_time = next_t;
            }
        }
        return cur_time;
    }
};

class Solution {
    public int findCrossingTime(int n, int k, int[][] time) {
        java.util.PriorityQueue<int[]> leftWait = new java.util.PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));
        java.util.PriorityQueue<int[]> rightWait = new java.util.PriorityQueue<>((a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));
        java.util.PriorityQueue<int[]> leftWork = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        java.util.PriorityQueue<int[]> rightWork = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));

        for (int i = 0; i < k; i++) {
            int p = time[i][0] + time[i][2];
            leftWait.offer(new int[]{p, i});
        }

        int curTime = 0;
        int remBoxes = n;

        while (remBoxes > 0 || !rightWait.isEmpty() || !rightWork.isEmpty()) {
            while (!leftWork.isEmpty() && leftWork.peek()[0] <= curTime) {
                int[] w = leftWork.poll();
                leftWait.offer(new int[]{w[1], w[2]});
            }
            while (!rightWork.isEmpty() && rightWork.peek()[0] <= curTime) {
                int[] w = rightWork.poll();
                rightWait.offer(new int[]{w[1], w[2]});
            }

            if (!rightWait.isEmpty()) {
                int[] w = rightWait.poll();
                int i = w[1];
                curTime += time[i][2];
                leftWork.offer(new int[]{curTime + time[i][3], w[0], i});
            } else if (remBoxes > 0 && !leftWait.isEmpty()) {
                int[] w = leftWait.poll();
                int i = w[1];
                curTime += time[i][0];
                remBoxes--;
                rightWork.offer(new int[]{curTime + time[i][1], w[0], i});
            } else {
                int nextT = Integer.MAX_VALUE;
                if (!leftWork.isEmpty()) nextT = Math.min(nextT, leftWork.peek()[0]);
                if (!rightWork.isEmpty()) nextT = Math.min(nextT, rightWork.peek()[0]);
                curTime = nextT;
            }
        }
        return curTime;
    }
}

var findCrossingTime = function(n, k, time) {
    class Heap {
        constructor(comparator) {
            this.data = [];
            this.comp = comparator;
        }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        peek() { return this.data[0]; }
        size() { return this.data.length; }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.comp(this.data[i], this.data[p]) < 0) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.comp(this.data[left], this.data[best]) < 0) best = left;
                if (right < len && this.comp(this.data[right], this.data[best]) < 0) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const compWait = (a, b) => a[0] !== b[0] ? b[0] - a[0] : b[1] - a[1];
    const compWork = (a, b) => a[0] - b[0];

    const leftWait = new Heap(compWait);
    const rightWait = new Heap(compWait);
    const leftWork = new Heap(compWork);
    const rightWork = new Heap(compWork);

    for (let i = 0; i < k; i++) {
        const p = time[i][0] + time[i][2];
        leftWait.push([p, i]);
    }

    let curTime = 0;
    let remBoxes = n;

    while (remBoxes > 0 || rightWait.size() > 0 || rightWork.size() > 0) {
        while (leftWork.size() > 0 && leftWork.peek()[0] <= curTime) {
            const w = leftWork.pop();
            leftWait.push([w[1], w[2]]);
        }
        while (rightWork.size() > 0 && rightWork.peek()[0] <= curTime) {
            const w = rightWork.pop();
            rightWait.push([w[1], w[2]]);
        }

        if (rightWait.size() > 0) {
            const w = rightWait.pop();
            const i = w[1];
            curTime += time[i][2];
            leftWork.push([curTime + time[i][3], w[0], i]);
        } else if (remBoxes > 0 && leftWait.size() > 0) {
            const w = leftWait.pop();
            const i = w[1];
            curTime += time[i][0];
            remBoxes--;
            rightWork.push([curTime + time[i][1], w[0], i]);
        } else {
            let nextT = Infinity;
            if (leftWork.size() > 0) nextT = Math.min(nextT, leftWork.peek()[0]);
            if (rightWork.size() > 0) nextT = Math.min(nextT, rightWork.peek()[0]);
            curTime = nextT;
        }
    }
    return curTime;
};
